#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(int *)a - *(int *)b);
}

int main() {
    int R, N;
    if (scanf("%d %d", &R, &N) != 2) return 0;

    int min_price[101];
    for (int i = 0; i <= 100; i++) {
        min_price[i] = -1;
    }

    for (int i = 0; i < N; i++) {
        int t, p;
        scanf("%d %d", &t, &p);
        if (min_price[t] == -1 || p < min_price[t]) {
            min_price[t] = p;
        }
    }

    int prices[101];
    int count = 0;
    for (int i = 1; i <= 100; i++) {
        if (min_price[i] != -1) {
            prices[count++] = min_price[i];
        }
    }

    qsort(prices, count, sizeof(int), cmp);

    int ans = 0;
    for (int i = 0; i < count; i++) {
        if (R >= prices[i]) {
            R -= prices[i];
            ans++;
        } else {
            break;
        }
    }

    printf("%d\n", ans);

    return 0;
}
